# This generator produces UTF-8 text buffers intended for FUZZ_PARAM_STR and
# FUZZ_PARAM_FILENAME in libxml2-related fuzzers. It focuses on well-formed
# XML/HTML snippets and identifier-like tokens (names, URIs, prefixes), as
# many stubs expect valid XML docs, QNames, URIs, encoding labels, etc.

# Key goals:
# - Frequently return small, valid XML/HTML documents to seed parsers/C14N.
# - Sometimes return namespace prefixes, QNames, attribute names/values.
# - Provide public/system IDs, URIs (absolute/relative), and encoding names.
# - Occasionally return strings that start with '&' for entity parsing.
# - Keep output size <= 4096 bytes.

XML_DECLS = [
    "<?xml version=\"1.0\"?>",
    "<?xml version=\"1.0\" encoding=\"UTF-8\"?>",
    "<?xml version=\"1.1\"?>",
]

HTML_DOC_TEMPLATES = [
    "<html><head><title>{title}</title></head><body>{body}</body></html>",
    "<html><body><p>{body}</p></body></html>",
]

XML_DOC_TEMPLATES = [
    "{decl}<root>{content}</root>",
    "{decl}<a xmlns=\"http://example.com/ns\" id=\"id1\">{content}</a>",
    "{decl}<r xmlns:x=\"urn:x\"><x:e a=\"{attr}\">{content}</x:e></r>",
    "{decl}<doc xml:lang=\"en\"><n1/><n2>{content}</n2></doc>",
]

# Some common encodings and aliases used by libxml2
ENCODINGS = [
    "UTF-8", "utf-8", "UTF-16", "utf-16", "UTF-16LE", "UTF-16BE",
    "ISO-8859-1", "iso-8859-1", "windows-1252", "ASCII", "US-ASCII",
]

# Common HTML entities and tags
HTML_ENTITIES = ["amp", "lt", "gt", "quot", "apos", "nbsp"]
HTML_TAGS = [
    "div", "span", "p", "a", "ul", "li", "script", "style", "meta", "title",
]

# Some URI bases and paths
URI_SCHEMES = ["http", "https", "file", "ftp", "urn"]
URI_HOSTS = ["example.com", "localhost", "xn--exmple-cua.com"]
URI_PATHS = ["/", "/a", "/a/b", "/path/with%20space", "/x?y=z", "/#frag"]

# Public/System ID seeds
PUBID_PARTS = [
    "-//W3C//DTD XHTML 1.0 Strict//EN",
    "-//OASIS//DTD DocBook XML V4.5//EN",
    "-//Example//ENTITIES Test//EN",
]
SYSID_PARTS = [
    "http://www.w3.org/TR/xhtml1/DTD/xhtml1-strict.dtd",
    "http://example.com/dtd/test.dtd",
    "file:///etc/example.dtd",
]

# Safe random XML Name production (XML 1.0 simplified)
NAME_START = string.ascii_letters + ":_"
NAME_CHARS = NAME_START + string.digits + "-.\u00B7\u0300\u036F\u203F\u2040"

def rand_name(rng: random.Random, minlen=1, maxlen=12) -> str:
    l = rng.randint(minlen, maxlen)
    s = rng.choice(NAME_START)
    for _ in range(l - 1):
        s += rng.choice(NAME_CHARS)
    return s

# Random text content avoiding invalid XML comment sequences when used in comments
SAFE_TEXT_CHARS = string.ascii_letters + string.digits + string.punctuation + " \t\n"

def rand_safe_text(rng: random.Random, minlen=0, maxlen=64) -> str:
    l = rng.randint(minlen, maxlen)
    s = ''.join(rng.choice(SAFE_TEXT_CHARS) for _ in range(l))
    # Clean comment-forbidden patterns if used as comment later
    s = s.replace("--", "- -")
    if s.endswith('-'):
        s += 'x'
    return s

# Build a valid-ish absolute or relative URI

def rand_uri(rng: random.Random) -> str:
    if rng.random() < 0.6:
        scheme = rng.choice(URI_SCHEMES)
        host = rng.choice(URI_HOSTS)
        path = rng.choice(URI_PATHS)
        return f"{scheme}://{host}{path}"
    else:
        # relative
        return rng.choice(["./a", "../b", "a/b", "#frag", "?q=x", ""]) or "a"

# Build a small valid XML document

def build_xml_doc(rng: random.Random, budget: int) -> bytes:
    decl = rng.choice(XML_DECLS)
    content = []
    # optionally add entity ref and CDATA/text
    if rng.random() < 0.5:
        ent = rng.choice(HTML_ENTITIES)
        content.append(f"&{ent};")
    if rng.random() < 0.5:
        content.append(rand_safe_text(rng, 0, 60))
    if rng.random() < 0.5:
        nm = rand_name(rng)
        content.append(f"<{nm}>{rand_safe_text(rng,0,24)}</{nm}>")
    attr = rand_safe_text(rng, 0, 16)
    tpl = rng.choice(XML_DOC_TEMPLATES)
    s = tpl.format(decl=decl, content=''.join(content), attr=attr)
    b = s.encode('utf-8')
    if len(b) > budget:
        b = b[:budget]
    return b

# Build a small valid HTML document

def build_html_doc(rng: random.Random, budget: int) -> bytes:
    title = rand_safe_text(rng, 1, 24)
    body_parts: List[str] = []
    # Some links and entities
    if rng.random() < 0.5:
        href = rand_uri(rng)
        body_parts.append(f"<a href=\"{href}\">{rand_safe_text(rng,1,16)}</a>")
    if rng.random() < 0.5:
        body_parts.append(f"&{rng.choice(HTML_ENTITIES)};")
    if rng.random() < 0.4:
        tag = rng.choice(HTML_TAGS)
        body_parts.append(f"<{tag}>{rand_safe_text(rng,0,20)}</{tag}>")
    tpl = rng.choice(HTML_DOC_TEMPLATES)
    s = tpl.format(title=title, body=''.join(body_parts) or "ok")
    b = s.encode('utf-8')
    if len(b) > budget:
        b = b[:budget]
    return b

# QName, prefix, attribute tokens

def build_qname(rng: random.Random) -> str:
    if rng.random() < 0.5:
        return rand_name(rng)  # local only
    return f"{rand_name(rng)}:{rand_name(rng)}"

# Public/System ID like strings or encoding labels

def build_id_or_encoding(rng: random.Random) -> str:
    pick = rng.random()
    if pick < 0.4:
        return rng.choice(PUBID_PARTS)
    if pick < 0.8:
        return rng.choice(SYSID_PARTS)
    return rng.choice(ENCODINGS)

# Entity ref starter for htmlParseEntityRef expectations

def build_entity_ref(rng: random.Random) -> str:
    return f"&{rng.choice(HTML_ENTITIES)};"

# Catalog-related type/orig/repl often want alnum-ish

def build_alnum(rng: random.Random, minlen=1, maxlen=24) -> str:
    chars = string.ascii_letters + string.digits + "-_:."  # safe
    l = rng.randint(minlen, maxlen)
    return ''.join(rng.choice(chars) for _ in range(l))

# Main entry

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    budget = 4096
    # Choose a profile to maximize coverage across many stubs
    choice = rng.random()

    if choice < 0.20:
        # Small valid XML doc (good for xmlC14N* and many xmlRead* paths)
        return build_xml_doc(rng, budget)
    if choice < 0.35:
        # Small valid HTML doc
        return build_html_doc(rng, budget)
    if choice < 0.45:
        # URI string
        return rand_uri(rng).encode('utf-8')
    if choice < 0.55:
        # QName or attribute name
        return build_qname(rng).encode('utf-8')
    if choice < 0.60:
        # Entity ref starter
        return build_entity_ref(rng).encode('utf-8')
    if choice < 0.70:
        # Encoding/Public/System IDs
        return build_id_or_encoding(rng).encode('utf-8')
    if choice < 0.80:
        # Catalog-ish tokens or filenames-like
        s = build_alnum(rng)
        if rng.random() < 0.5:
            # add simple extension for filenames
            s += rng.choice([".xml", ".html", ".xsd", ".dtd", ".txt"])  
        return s.encode('utf-8')
    if choice < 0.90:
        # Namespace prefix tokens list (for inclusive_ns_prefixes usage)
        n = rng.randint(1, 3)
        parts = [rand_name(rng, 1, 6) for _ in range(n)]
        return (' '.join(parts)).encode('utf-8')
    # Fallback: random safe text (bounded)
    return rand_safe_text(rng, 0, 256).encode('utf-8')

import os
import random
import string
from typing import List

# Generator for a delimited path list intended for xmlLoadCatalogs(const char* list)
# The function typically expects a list of catalog file paths separated by whitespace
# or platform-specific separators. We'll generate realistic combinations:
# - Absolute and relative paths
# - With spaces and quotes
# - Environment-like tilde expansion tokens
# - Different separators (space, newline, tab, semicolon) to exercise parsing
# - Common catalog file extensions (.xml, .cat, .catalog)
# We return bytes so the fuzzer can feed it directly.

EXTS = [".xml", ".cat", ".catalog", ""]
DIR_NAMES = [
    "etc", "usr", "local", "share", "xml", "catalog", "dtd", "schemas",
    "..", ".", "opt", "var", "tmp", "home", "lib", "lib64"
]
BASE_NAMES = [
    "catalog", "catalogs", "sgml", "xmlcatalog", "docbook", "entities",
    "local-catalog", "system", "public", "fallback", "main", "custom"
]
SEP_SETS: List[List[str]] = [
    [" "],                      # single space
    ["\n"],                     # newline-delimited
    ["\t"],                     # tab-delimited
    [" ", "\n"],               # mix space/newline
    [";"],                      # semicolon-delimited (Windows-style scenarios)
]

WIN_DRIVES = [f"{chr(c)}:" for c in range(ord('C'), ord('H'))]

def _rand_bool(r: random.Random, p: float = 0.5) -> bool:
    return r.random() < p

def _rand_word(r: random.Random, pool: List[str]) -> str:
    return r.choice(pool)

def _rand_component(r: random.Random) -> str:
    # Mix directory names with random tokens
    if _rand_bool(r, 0.25):
        # small random token
        letters = string.ascii_letters + string.digits + "_-"
        return ''.join(r.choice(letters) for _ in range(r.randint(1, 8)))
    return _rand_word(r, DIR_NAMES)

def _maybe_ext(r: random.Random) -> str:
    return r.choice(EXTS)

def _maybe_quoted(r: random.Random, path: str) -> str:
    # Occasionally add quotes if path contains spaces or randomly otherwise
    if ' ' in path or _rand_bool(r, 0.2):
        # randomly choose single or double quotes
        if _rand_bool(r, 0.5):
            return '"' + path.replace('"', '\\"') + '"'
        else:
            return "'" + path.replace("'", "\\'") + "'"
    return path

def _maybe_env_or_tilde(r: random.Random, path: str) -> str:
    # Prepend ~ or %VAR% or $VAR occasionally
    choice = r.randint(0, 4)
    if choice == 0:
        return "~" + ("/" if not path.startswith(('/', '\\')) else "") + path
    elif choice == 1:
        var = r.choice(["HOME", "USERPROFILE", "TMP", "TEMP", "XDG_DATA_DIRS"]) \
              if _rand_bool(r, 0.7) else ''.join(r.choice(string.ascii_uppercase) for _ in range(r.randint(3,8)))
        return f"${var}/" + path if not path.startswith(('/', '\\')) else f"${var}" + path
    elif choice == 2:
        var = r.choice(["APPDATA", "LOCALAPPDATA", "PROGRAMDATA"]) \
              if _rand_bool(r, 0.7) else ''.join(r.choice(string.ascii_uppercase) for _ in range(r.randint(3,8)))
        sep = "\\" if _rand_bool(r, 0.7) else "/"
        return f"%{var}%{sep}" + path.replace('/', sep)
    else:
        return path

def _build_unix_path(r: random.Random) -> str:
    parts = []
    # absolute or relative
    if _rand_bool(r, 0.6):
        parts.append("/")
    depth = r.randint(1, 5)
    for _ in range(depth):
        parts.append(_rand_component(r))
    base = _rand_word(r, BASE_NAMES)
    ext = _maybe_ext(r)
    parts.append(base + ext)
    path = "/".join([p for p in parts if p != "/"]) if parts[0] != "/" else "/" + "/".join(parts[1:])
    # Occasionally inject spaces within components to test quoting behavior
    if _rand_bool(r, 0.15):
        tokens = path.split('/')
        if len(tokens) > 2:
            i = r.randint(1, len(tokens)-1)
            tokens[i] = tokens[i] + " " + _rand_word(r, ["data", "files", "catalog"])
            path = "/".join(tokens)
    path = _maybe_env_or_tilde(r, path)
    return _maybe_quoted(r, path)

def _build_windows_path(r: random.Random) -> str:
    drive = r.choice(WIN_DRIVES)
    sep = "\\"
    depth = r.randint(1, 5)
    parts = [drive]
    for _ in range(depth):
        parts.append(_rand_component(r))
    base = _rand_word(r, BASE_NAMES) + _maybe_ext(r)
    parts.append(base)
    path = sep.join(parts)
    # Possibly add spaces
    if _rand_bool(r, 0.2):
        idx = r.randint(1, len(parts)-1)
        parts[idx] = parts[idx] + " " + _rand_word(r, ["data", "files"]) 
        path = sep.join(parts)
    # Maybe convert to UNC or relative
    if _rand_bool(r, 0.1):
        path = "\\\\server\\share" + sep + sep.join(parts[1:])
    if _rand_bool(r, 0.15):
        # make relative
        rel_depth = r.randint(0, 2)
        rel_prefix = sep.join([".."] * rel_depth) if rel_depth else "."
        path = rel_prefix + sep + sep.join(parts[1:])
    path = _maybe_env_or_tilde(r, path.replace("/", sep))
    return _maybe_quoted(r, path)

def _one_path(r: random.Random) -> str:
    if _rand_bool(r, 0.5):
        return _build_unix_path(r)
    else:
        return _build_windows_path(r)

def _choose_separators(r: random.Random) -> List[str]:
    return r.choice(SEP_SETS)

def _join_paths_with_seps(r: random.Random, paths: List[str], seps: List[str]) -> str:
    out = []
    for i, p in enumerate(paths):
        out.append(p)
        if i != len(paths) - 1:
            # choose a separator from the set; sometimes multiple in a row
            rep = r.randint(1, 3)
            for _ in range(rep):
                out.append(r.choice(seps))
    return ''.join(out)

def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # number of paths: 1..8 skewed toward more to exercise multiple loads
    count = 1 + int(r.paretovariate(2.0))
    count = max(1, min(count, 8))

    paths = []
    for _ in range(count):
        p = _one_path(r)
        # Sometimes prefix with file:// or file:\\\ style
        if _rand_bool(r, 0.25):
            if p.startswith(('\\\\',)) or (len(p) > 1 and p[1:3] == ':\\'):
                # windows style file URI
                uri = 'file:///' + p.replace('\\', '/')
                p = _maybe_quoted(r, uri)
            else:
                scheme = r.choice(['file://', 'file:///'])
                p = _maybe_quoted(r, scheme + p.lstrip('/'))
        paths.append(p)

    seps = _choose_separators(r)
    s = _join_paths_with_seps(r, paths, seps)

    # Ensure we don't exceed 4096 bytes; trim from the end at separator boundary if needed
    b = s.encode('utf-8', errors='strict')
    if len(b) > 4096:
        # Try to trim at last separator before limit
        cutoff = 4096
        view = b[:cutoff]
        # find last ASCII separator position
        last_sep = max(view.rfind(c.encode()) for c in [' ', '\n', '\t', ';'])
        if last_sep > 0:
            b = view[:last_sep]
        else:
            b = view
    return b

import random
import string
from typing import List, Tuple

# This generator creates valid, NUL-terminated UTF-8 XPath/XPointer expressions
# to feed FUZZ_PARAM_STR() in the provided fuzzer stubs. It aims to cover:
# - Absolute/relative paths, wildcards, descendant axes
# - Predicates, attribute tests, numeric and boolean ops
# - Functions (string, count, contains, starts-with, normalize-space, name, local-name, namespace-uri)
# - Namespaces via prefix usage (prefixes that are plausible identifiers)
# - Union (|), arithmetic, comparison
# - XPointer-wrapped XPath (xpointer(), xpath1()), element() scheme
# - Short expressions such as literals and numbers
# Expressions are kept fairly short to be fast and likely valid.

# Some reasonable element and attribute names
ELEM_NAMES = [
    "root", "a", "b", "c", "item", "node", "book", "title", "author",
    "chapter", "section", "para", "div", "span", "ul", "li", "entry",
    "data", "row", "col"
]
ATTR_NAMES = [
    "id", "name", "class", "type", "lang", "xml:lang", "role",
    "href", "title", "value", "count", "index"
]
# plausible namespace prefixes
NS_PREFIXES = ["ns", "p", "q", "x", "h", "xhtml", "ex", "u"]

# XPath functions to sample, mapped to small builders
def fn_string(expr: str) -> str:
    return f"string({expr})"

def fn_count(expr: str) -> str:
    return f"count({expr})"

def fn_contains(a: str, b: str) -> str:
    return f"contains({a}, {b})"

def fn_starts_with(a: str, b: str) -> str:
    return f"starts-with({a}, {b})"

def fn_normalize_space(expr: str) -> str:
    return f"normalize-space({expr})"

def fn_name(expr: str) -> str:
    return f"name({expr})"

def fn_local_name(expr: str) -> str:
    return f"local-name({expr})"

def fn_namespace_uri(expr: str) -> str:
    return f"namespace-uri({expr})"

FUNC_BUILDERS = [
    lambda r: fn_string(sample_path(r)),
    lambda r: fn_count(sample_path(r)),
    lambda r: fn_contains("'" + sample_literal(r) + "'", "'" + sample_literal(r) + "'"),
    lambda r: fn_starts_with("'" + sample_literal(r) + "'", "'" + sample_literal(r) + "'"),
    lambda r: fn_normalize_space("'" + sample_literal(r) + "'"),
    lambda r: fn_name(sample_node_test(r)),
    lambda r: fn_local_name(sample_node_test(r)),
    lambda r: fn_namespace_uri(sample_node_test(r)),
]

# Helpers to build valid identifiers
def ident_start(r: random.Random) -> str:
    choices = string.ascii_letters + "_"
    return r.choice(choices)

def ident_part(r: random.Random) -> str:
    choices = string.ascii_letters + string.digits + "_-\."
    return r.choice(choices)

def make_prefix(r: random.Random) -> str:
    if r.random() < 0.5:
        return r.choice(NS_PREFIXES)
    # random but valid NCName-ish
    length = r.randint(1, 6)
    return ident_start(r) + "".join(ident_part(r) for _ in range(length-1))

def qname(r: random.Random) -> str:
    if r.random() < 0.5:
        return r.choice(ELEM_NAMES)
    return f"{make_prefix(r)}:{r.choice(ELEM_NAMES)}"

def attr_name(r: random.Random) -> str:
    if r.random() < 0.7:
        return r.choice(ATTR_NAMES)
    return ident_start(r) + "".join(ident_part(r) for _ in range(r.randint(0,5)))

def sample_literal(r: random.Random) -> str:
    # return a simple ASCII literal without quotes
    pool = " abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_:/.,"
    n = r.randint(0, 12)
    return "".join(r.choice(pool) for _ in range(n))

def sample_number(r: random.Random) -> str:
    if r.random() < 0.4:
        return str(r.randint(0, 20))
    return f"{r.randint(0, 10)}.{r.randint(0, 999)}"

def axis_or_abbrev(r: random.Random) -> str:
    axes = ["child::", "descendant::", "self::", "descendant-or-self::", "attribute::"]
    if r.random() < 0.3:
        return r.choice(axes)
    return ""  # most often abbreviated

def node_test(r: random.Random) -> str:
    choices = [qname(r), "*", "node()", "text()", "comment()", "processing-instruction()"]
    return r.choice(choices)

def sample_node_test(r: random.Random) -> str:
    # something that can serve as an argument for name()/local-name()/namespace-uri()
    if r.random() < 0.5:
        return "/" + qname(r)
    return r.choice([".", "..", "/*", "//" + qname(r)])

def predicate(r: random.Random) -> str:
    # a few valid predicate forms
    forms = []
    # attribute equality
    forms.append(f"@{attr_name(r)}='" + sample_literal(r) + "'")
    # numeric position
    forms.append(f"position()={sample_number(r)}")
    # contains on attribute
    forms.append("contains(@" + attr_name(r) + ", '" + sample_literal(r) + "')")
    # boolean attribute existence
    forms.append("@" + attr_name(r))
    return "[" + r.choice(forms) + "]"

def step(r: random.Random) -> str:
    a = axis_or_abbrev(r)
    nt = node_test(r)
    seg = a + nt
    # maybe attach predicate(s)
    k = r.choices([0,1,2], weights=[0.4, 0.4, 0.2])[0]
    for _ in range(k):
        seg += predicate(r)
    return seg

def sample_path(r: random.Random) -> str:
    # Build a short valid path
    parts: List[str] = []
    start = r.random()
    if start < 0.33:
        parts.append("")  # absolute path begins with /
    elif start < 0.66:
        parts.append(".")  # relative current node
    else:
        parts.append("..")
    # Add 1-3 steps, maybe using // abbreviation
    nsteps = r.randint(1, 3)
    out = "/".join([p for p in parts if p != ""]) if parts[0] != "" else "/"
    if out and not out.endswith("/"):
        out += "/"
    for i in range(nsteps):
        if i > 0 and r.random() < 0.35:
            out += "//"
        out += step(r)
        if i != nsteps-1 and not out.endswith("//"):
            out += "/"
    return out

def sample_union(r: random.Random) -> str:
    return sample_path(r) + " | " + sample_path(r)

def sample_op_expr(r: random.Random) -> str:
    # combine path/count with comparisons or arithmetic
    left = r.choice([
        sample_path(r),
        fn_count(sample_path(r)),
        fn_string(sample_path(r)),
        "'" + sample_literal(r) + "'",
        sample_number(r)
    ])
    right = r.choice([
        sample_path(r),
        fn_count(sample_path(r)),
        "'" + sample_literal(r) + "'",
        sample_number(r)
    ])
    op = r.choice(["=", "!=", "<", ">", "<=", ">=", "+", "-", "*", "div", "mod", "and", "or"])
    return f"{left} {op} {right}"

def sample_function_call(r: random.Random) -> str:
    builder = r.choice(FUNC_BUILDERS)
    return builder(r)

def sample_xpath(r: random.Random) -> str:
    # Pick among several families; ensure non-empty
    pick = r.random()
    if pick < 0.25:
        expr = sample_path(r)
    elif pick < 0.45:
        expr = sample_union(r)
    elif pick < 0.70:
        expr = sample_op_expr(r)
    elif pick < 0.90:
        expr = sample_function_call(r)
    else:
        # simple literal or number is a valid expression too
        expr = r.choice(["'" + sample_literal(r) + "'", sample_number(r)])
    # Optionally wrap with parentheses
    if r.random() < 0.25:
        expr = f"({expr})"
    return expr

def sample_xpointer(r: random.Random, base_xpath: str) -> str:
    scheme = r.randint(0, 3)
    if scheme == 0:
        return f"xpointer({base_xpath})"
    if scheme == 1:
        return f"xpath1({base_xpath})"
    if scheme == 2:
        # element() scheme: either ID or child sequence like /1/2
        if r.random() < 0.5:
            # id style token
            token = ident_start(r) + "".join(ident_part(r) for _ in range(r.randint(0,6)))
            return f"element({token})"
        else:
            # child sequence starting from root, e.g., /1/2/3
            depth = r.randint(1, 4)
            seq = "/" + "/".join(str(r.randint(1, 4)) for _ in range(depth))
            return f"element({seq})"
    # xmlns() prelude + xpointer()
    prefix = make_prefix(r)
    uri = "http://example.com/" + prefix
    inner = base_xpath
    return f"xmlns({prefix}\"{uri}\") xpointer({inner})"


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Build either pure XPath or XPointer-wrapped XPath. Ensure NUL-terminated bytes output.
    base = sample_xpath(r)
    if r.random() < 0.35:
        expr = sample_xpointer(r, base)
    else:
        expr = base
    # Keep size under 4096, UTF-8 safe ASCII
    expr = expr[:1000]
    # Ensure it's non-empty and NUL-terminated for C APIs expecting C-strings
    if not expr:
        expr = "/node()"
    return (expr + "\x00").encode("utf-8")
